import{_ as a}from"./chunks/thumb-05.AvrSnx83.js";import{_ as r}from"./chunks/photo-05.BHbHZC90.js";import{_ as e,H as s,f as d,i as o}from"./chunks/framework.Cvt1eIE0.js";const m=JSON.parse('{"title":"Windsurf 使用教程：Cascade 流式编辑与 AI IDE 入门","description":"","frontmatter":{"title":"Windsurf 使用教程：Cascade 流式编辑与 AI IDE 入门","date":"2026-05-22T00:00:00.000Z","category":"技术","tags":["AI","Windsurf","教程"],"excerpt":"Codeium 出品的 AI IDE：Cascade 多步推理、Flows 工作流与和 Cursor 的差异选型。"},"headers":[],"relativePath":"posts/技术/windsurf-ai-ide-tutorial.md","filePath":"posts/技术/windsurf-ai-ide-tutorial.md"}'),i={name:"posts/技术/windsurf-ai-ide-tutorial.md"};function n(l,t,h,p,u,c){return s(),d("div",null,[...t[0]||(t[0]=[o('<img src="'+a+'" alt="配图" class="article-banner" loading="lazy"><div class="figure wide"><img src="'+r+`" alt="随拍配图" loading="lazy"><p class="figure-caption">多步推理像瀑布，一步接一步把任务冲到底。</p></div><h1 id="windsurf-使用教程" tabindex="-1">Windsurf 使用教程 <a class="header-anchor" href="#windsurf-使用教程" aria-label="Permalink to &quot;Windsurf 使用教程&quot;">​</a></h1><p><a href="https://windsurf.com" target="_blank" rel="noreferrer">Windsurf</a>（原 Codeium 编辑器路线）是与 Cursor 同类的 <strong>AI-native IDE</strong>，主打 <strong>Cascade</strong>——把「理解 → 规划 → 改文件 → 跑终端」串成连续流，减少你在 Chat 与编辑器之间来回粘贴。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ol><li>官网下载对应系统安装包（注意 Apple Silicon / Intel）。</li><li>注册 Codeium / Windsurf 账号并选择套餐（Free 档通常有额度限制）。</li><li>可选导入 VS Code 配置，缩短上手时间。</li></ol><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td><strong>Cascade</strong></td><td>多步 Agent，自动拆任务并连续执行，适合中等规模功能开发</td></tr><tr><td><strong>Flows</strong></td><td>可保存的重复流程（如「加 API + 测试 + 文档」）</td></tr><tr><td><strong>补全</strong></td><td>行级预测，与 Cascade 互补</td></tr><tr><td><strong>上下文</strong></td><td>自动索引仓库，也可 <code>@</code> 指定文件</td></tr></tbody></table><h2 id="推荐使用方式" tabindex="-1">推荐使用方式 <a class="header-anchor" href="#推荐使用方式" aria-label="Permalink to &quot;推荐使用方式&quot;">​</a></h2><h3 id="日常小改" tabindex="-1">日常小改 <a class="header-anchor" href="#日常小改" aria-label="Permalink to &quot;日常小改&quot;">​</a></h3><p>用行级补全 + 局部 Chat，和 Copilot/Cursor 类似。</p><h3 id="功能级开发" tabindex="-1">功能级开发 <a class="header-anchor" href="#功能级开发" aria-label="Permalink to &quot;功能级开发&quot;">​</a></h3><p>在 Cascade 面板输入<strong>带验收标准</strong>的任务，例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在 lib/checkout/ 实现优惠券校验：</span></span>
<span class="line"><span>- 新增 CouponValidator</span></span>
<span class="line"><span>- 单元测试覆盖过期、叠加、非法码</span></span>
<span class="line"><span>- 不要修改 payment_gateway.dart</span></span></code></pre></div><p>等待 Cascade 分步执行，<strong>每步 diff 可中断或回滚</strong>。</p><h3 id="团队规范" tabindex="-1">团队规范 <a class="header-anchor" href="#团队规范" aria-label="Permalink to &quot;团队规范&quot;">​</a></h3><p>在项目根添加说明文件（名称以 Windsurf 当前文档为准，常见为规则/记忆文件），写明：</p><ul><li>目录结构与命名</li><li>必须跑的 CI 命令</li><li>禁止修改的路径</li></ul><h2 id="与-cursor-如何二选一" tabindex="-1">与 Cursor 如何二选一 <a class="header-anchor" href="#与-cursor-如何二选一" aria-label="Permalink to &quot;与 Cursor 如何二选一&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Windsurf</th><th>Cursor</th></tr></thead><tbody><tr><td>多步自动化</td><td>Cascade 流式串联</td><td>Composer / Agent</td></tr><tr><td>生态</td><td>较新，扩展在追赶</td><td>VS Code 迁移成熟</td></tr><tr><td>定价</td><td>以官网为准</td><td>以官网为准</td></tr><tr><td>手感</td><td>偏「一条龙」</td><td>偏「编辑器 + Agent 面板」</td></tr></tbody></table><p>建议各试用一周，用<strong>同一仓库同一任务</strong>（如加一个 API 模块）对比 diff 质量与速度。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：Cascade 改太多怎么办？</strong><br> A：Git 分支 + 限制提示词目录；要求「每步先列出将改的文件清单」。</p><p><strong>Q：公司仓库能用吗？</strong><br> A：查看 Windsurf/Codeium 企业条款与隐私模式；涉密代码走私有化方案。</p><p><strong>Q：和 Claude Code 关系？</strong><br> A：Windsurf 是 IDE；Claude Code 是终端 Agent，可互补而非替代。</p><hr><p><em>功能命名与订阅以 Windsurf 官网为准。</em></p>`,27)])])}const C=e(i,[["render",n]]);export{m as __pageData,C as default};
